import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Contracts Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Contracts Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/contracts-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Contracts Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/contracts-overview"}]]},"headers":[],"relativePath":"user-guide/contracts-overview.md","filePath":"user-guide/contracts-overview.md","lastUpdated":1787271837000}'),i={name:"user-guide/contracts-overview.md"};function n(s,e,d,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="contracts-module" tabindex="-1">Contracts Module <a class="header-anchor" href="#contracts-module" aria-label="Permalink to &quot;Contracts Module&quot;">​</a></h1><p>Sales contract-tracking module on the frozen platform. Mirrors the <a href="/user-guide/opportunities-overview">Opportunities</a> / <a href="/user-guide/quotations-overview">Quotations</a> notes/timeline/assignment pattern, kept lean (no line items — a contract is a single signed agreement record).</p><p><strong>Hard dependency:</strong> Contracts requires the <strong>Opportunities</strong> module — Marketplace install is blocked until Opportunities is entitled. Contracts may <strong>optionally</strong> link a Quotation once the Quotations module is also entitled.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/contracts">contracts.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/contracts">contracts.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/contracts">contracts.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/opportunities-overview">opportunities.md</a> · <a href="/user-guide/quotations-overview">quotations.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-contracts">../api/tenant-v1-contracts.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Contract fields: opportunity (required), optional quotation link, title, party name, start date (required), optional end date, value, currency, rich-text description and notes</li><li>Status workflow: <code>draft → active → expired | terminated</code> (<code>POST /contracts/{id}/status</code>)</li><li><strong>Create invoice</strong> (<code>POST /contracts/{id}/convert</code>) — repeatable draft CustomerInvoice from an active contract when Invoices is entitled (soft check). Confirming in the UI acknowledges repeat billing (<code>acknowledge_repeat_billing</code>); the API requires that flag for the second and later invoices from the same contract.</li><li>Assignment with assignee scoping via <code>contracts.assign</code></li><li>Notes + domain activity timeline (mirrors Opportunities / Quotations)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:contracts</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong> (Sales category)</li><li>Audit + activity logging; assignment notification</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>contracts.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code> · <code>convert</code></p><p>Enable Contracts from Marketplace (free) once Opportunities is installed. Catalog: slug <code>contracts</code>, category <code>sales</code>, <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 60</code>.</p><h2 id="related-modules" tabindex="-1">Related modules <a class="header-anchor" href="#related-modules" aria-label="Permalink to &quot;Related modules&quot;">​</a></h2><p><strong>Hard dependency:</strong> Opportunities (see <a href="/architecture/module-dependencies">Module Dependencies</a>). <strong>Optional:</strong> Quotations — the quotation picker on a contract only appears (and validates) when Quotations is entitled. <strong>Optional:</strong> Invoices — create-invoice is hidden until Invoices is entitled.</p><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Contract PDF export / e-signature</li><li>Renewal reminders</li><li>Multi-currency conversion</li></ul>',14)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
